fn timed_insert(idx: &VectorIndex, corpus: &[Vec<f32>]) -> Duration {
    let t = Instant::now();
    for (i, v) in corpus.iter().enumerate() {
        idx.insert(key_for(i), v).expect("insert");
    }
    t.elapsed()
}

